-- Podcast episodes + photography catalog.
-- Metadata lives in Postgres (reached through the Cloudflare Hyperdrive binding),
-- media bytes stay in R2. Ids are generated by the Worker (crypto.randomUUID()).

create table if not exists podcast_episodes (
  id             uuid primary key,
  title          text        not null,
  published_on   date        not null default current_date,
  description    text        not null default '',
  duration       text        not null default '',
  audio_key      text        not null,
  audio_size     bigint      not null default 0,
  audio_type     text        not null default 'audio/mpeg',
  cover_key      text,
  author         text,
  episode_number integer,
  season         integer,
  keywords       text[]      not null default '{}',
  explicit       boolean     not null default false,
  created_at     timestamptz not null default now(),
  updated_at     timestamptz not null default now()
);

create index if not exists podcast_episodes_published_idx
  on podcast_episodes (published_on desc, created_at desc);

create table if not exists photos (
  id            uuid primary key,
  title         text        not null default '',
  description   text,
  collection    text        not null default 'uncategorized',
  taken_on      date,
  width         integer     not null default 0,
  height        integer     not null default 0,
  original_key  text        not null,
  original_size bigint      not null default 0,
  preview_key   text,
  preview_size  bigint      not null default 0,
  content_type  text        not null default 'image/jpeg',
  tags          text[]      not null default '{}',
  published     boolean     not null default true,
  sort_order    integer     not null default 0,
  created_at    timestamptz not null default now()
);

create index if not exists photos_collection_idx
  on photos (collection, taken_on desc nulls last, created_at desc);

create index if not exists photos_published_idx
  on photos (published, sort_order, created_at desc);
